-- ============================================================
-- Aspect of the Monkey: linkage
-- ============================================================

-- All three of 13163's effect slots are occupied and none is free:
--   E1 = SPELL_AURA_MOD_DODGE_PERCENT (49), bp 17 -> +18% dodge
--   E2 = SPELL_AURA_MOD_DAMAGE_PERCENT_TAKEN (87) at 0%, MiscValue 127
--   E3 = SPELL_AURA_PROC_TRIGGER_SPELL (42) -> 60798 'Monkey Speed'
-- E2 is a retail placeholder at zero, but it is the ONLY anchor the planned
-- 'Aspect Mastery' talent has for "Monkey -- damage taken reduced by 5%"
-- (TODO.md).  Clobbering it would silently destroy that talent's slot.
--
-- So the new benefits go on a hidden companion instead.  spell_linked_spell
-- type 2 (SPELL_LINK_AURA) applies 200740 when 13163's aura is applied
-- (SpellAuras.cpp:1242) and removes it when 13163 is removed (SpellAuras.cpp:1266).
-- No C++, no slot pressure, Aspect Mastery keeps E2.
DELETE FROM `spell_linked_spell` WHERE `spell_trigger` = 13163 AND `spell_effect` = 200740;
INSERT INTO `spell_linked_spell` (`spell_trigger`, `spell_effect`, `type`, `comment`) VALUES
(13163, 200740, 2, 'Aspect of the Monkey -> untrackable / melee AP / pet-aura carrier');

-- effectId is ZERO-BASED, so 2 = DBC Effect3, the SPELL_AURA_DUMMY on 200740.
-- pet = 0 means any pet.
-- Path: AuraEffect::HandleAuraDummy (SpellAuraEffects.cpp:5171)
--       -> Unit::AddPetAura (Unit.cpp:13753) -> Pet::CastPetAura (Unit.cpp:13777).
--
-- 200740's Effect3 deliberately uses TARGET_UNIT_CASTER (1), NOT TARGET_UNIT_PET:
-- SpellMgr.cpp:2485 derives removeOnChangePet from that field, and with
-- TARGET_UNIT_PET, Pet::CastPetAuras(false) would UNREGISTER the entry on every
-- pet swap.  With target 1 the registration persists and Pet::CastPetAuras
-- re-applies it to each newly summoned pet for free (Pet.cpp:2354).
DELETE FROM `spell_pet_auras` WHERE `aura` = 200741;
INSERT INTO `spell_pet_auras` (`spell`, `effectId`, `pet`, `aura`) VALUES
(200740, 2, 0, 200741);
